#!/usr/bin/env bash
# Removes everything up.sh created, in reverse order, then checks that nothing is left.
#   down.sh          asks for confirmation
#   down.sh --yes    does not ask
# Do not edit this file while it runs: bash reads a script as it goes.
set -uo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
export AWS_PAGER=""
if [ "${1:-}" != "--yes" ]; then
  read -r -p "This destroys both EKS clusters, the core network, every VPC and the DNS setup. Type 'destroy' to continue: " answer
  [ "$answer" = "destroy" ] || { echo "aborted"; exit 1; }
fi

# The load balancers and the Lattice services are created by controllers. Terraform deletes their Ingress and routes while the controllers
# still run, and deleting an Ingress waits for its load balancer, so nothing is left behind.
# The one thing it cannot see is the VPC association that the Lattice controller makes for the cluster's own VPC: it blocks the service network
# and the VPC, so remove it by hand, retrying because Lattice throttles.
lattice_cleanup() {
  for sn in $(aws vpc-lattice list-service-networks --region us-east-1 --query "items[?name=='ds05-lattice'].id" --output text 2>/dev/null); do
    for i in $(seq 1 12); do
      left=$(aws vpc-lattice list-service-network-vpc-associations --service-network-identifier "$sn" --region us-east-1 --query 'items[].id' --output text 2>/dev/null)
      [ -z "$left" ] && break
      for assoc in $left; do
        aws vpc-lattice delete-service-network-vpc-association --service-network-vpc-association-identifier "$assoc" --region us-east-1 >/dev/null 2>&1 || true
      done
      sleep 30
    done
    aws vpc-lattice delete-service-network --service-network-identifier "$sn" --region us-east-1 >/dev/null 2>&1 || true
  done
}
(cd "$ROOT/terraform/30-platform" && terraform destroy -input=false -auto-approve) || { lattice_cleanup; (cd "$ROOT/terraform/30-platform" && terraform destroy -input=false -auto-approve); }
lattice_cleanup
(cd "$ROOT/terraform/20-clusters" && terraform destroy -input=false -auto-approve) || (cd "$ROOT/terraform/20-clusters" && terraform destroy -input=false -auto-approve)
# Deleting a VPC that took its range from IPAM makes Terraform wait for IPAM to release the allocation, which takes a long time (tens of minutes).
(cd "$ROOT/terraform/10-network" && terraform destroy -input=false -auto-approve) || (cd "$ROOT/terraform/10-network" && terraform destroy -input=false -auto-approve)
"$ROOT/scripts/verify-clean.sh"
